// ?id=<AssemblyAI transcript id> from POST sales-outreach/transcribe.
const id = String(($json.query && $json.query.id) || '').trim();
if (!/^[A-Za-z0-9-]{8,64}$/.test(id)) {
  return { ok: false, statusCode: 400, body: { error: 'Missing or bad transcript id.' } };
}
return { ok: true, id };

// AssemblyAI transcript → { status, lines: [{ speaker: 'Speaker 1', text, start }] }.
// Speakers come back as A, B, C...; they are renamed 1, 2, 3 in the order
// they first talk. status: queued | processing | completed | error.
const t = $input.first().json;
if (!t.status) {
  return { statusCode: 502, body: { error: 'Transcript read failed: ' + String((t.error && t.error.message) || t.error || 'no status'), step: 'AssemblyAI: get transcript' } };
}
if (t.status === 'error') {
  return { statusCode: 200, body: { success: true, status: 'error', error: String(t.error || 'Transcription failed.') } };
}
if (t.status !== 'completed') {
  return { statusCode: 200, body: { success: true, status: t.status } };
}
const names = {};
let n = 0;
const lines = (Array.isArray(t.utterances) ? t.utterances : []).map((u) => {
  const k = String(u.speaker || '?');
  if (!names[k]) names[k] = 'Speaker ' + (++n);
  return { speaker: names[k], text: String(u.text || ''), start: Number(u.start) || 0 };
});
if (!lines.length && t.text) lines.push({ speaker: 'Speaker 1', text: String(t.text), start: 0 });
return { statusCode: 200, body: { success: true, status: 'completed', seconds: Number(t.audio_duration) || 0, speakers: n, lines } };
